(function(root){
 'use strict';
 const phases=[{id:'discovery',title:'Discovery',description:'Identify what is actually on this sled.'},{id:'inspection',title:'Inspection',description:'Record condition and decide what needs replacement.'},{id:'planning',title:'Parts plan',description:'Verify fitment before placing orders.'},{id:'repair',title:'Repair',description:'Track the work and resolve every required item.'},{id:'testing',title:'Checks & first run',description:'Record the service settings, checks and test results.'},{id:'finish',title:'Finish & handoff',description:'Close the project with photos and a maintenance record.'}];
 const field=(id,label,type='text',options={})=>({id,label,type,required:true,...options});
 const steps=[
  {id:'evidence',phase:'discovery',title:'Capture the identification photos',summary:'Complete the photo record before choosing a model-specific part.',instructions:['Photograph the complete sled, dashboard, engine identification and chassis plate or stamped markings.','Choose each matching photo below. If no chassis identifier survives, document where you looked instead of inventing a number.','Photos already supplied are offered below. A picture being present does not mean its numbers have been verified.'],fields:[field('overall','Overall sled view','photo'),field('dashboard','Dashboard / controls view','photo'),field('enginePhoto','Engine tag / identification view','photo'),field('plateDisposition','Chassis identifier','select',{options:['Plate / markings photographed','No plate or markings found']}),field('platePhoto','Chassis plate / markings photo','photo',{when:['plateDisposition','Plate / markings photographed']}),field('plateSearch','Where did you look? What is missing?','textarea',{when:['plateDisposition','No plate or markings found']})]},
  {id:'chassis',phase:'discovery',title:'Resolve the chassis identity',summary:'Separate the chassis year from the engine year.',instructions:['Compare the actual chassis and identification evidence with a factory reference.','For the early sled, 1963 remains a hypothesis. For the later sled, review the photographed code against SE8.','Record the supported conclusion and its source. “Unresolved” saves a draft and keeps this step open; it does not silently become confirmed.'],fields:[field('conclusion','Identification conclusion','select',{options:['Unresolved — more research needed','Confirmed from documented evidence']}),field('year','Chassis year','number',{min:1959,max:1996}),field('model','Chassis model / variant'),field('code','Chassis code / serial (or document that it is missing)'),field('reference','Factory reference or expert identification source','textarea'),field('reasoning','Explain how the evidence supports this identification','textarea')],checks:[['conclusion','Confirmed from documented evidence','The chassis identity is still unresolved. Record the missing evidence or research needed.']]},
  {id:'engine',phase:'discovery',title:'Identify the installed engine',summary:'Match engine parts to the engine in front of you.',instructions:['Read the installed engine tag and record the type, serial and displacement. Use the close-up in the archive as evidence.','If the engine differs from the original specification, record it as an installed-engine finding. A serial-year chart does not identify the chassis.','Do not infer the engine type from hood graphics.'],fields:[field('type','Installed Rotax type / engine model'),field('serial','Engine serial number'),field('displacement','Displacement as documented on engine / reference'),field('photo','Engine identification photo','photo'),field('reference','Source supporting installed engine identification','textarea'),field('fit','Original / replacement / unknown origin','select',{options:['Appears consistent with chassis','Replacement engine documented','Origin unknown; installed type identified']})]},
  {id:'carburetor',phase:'discovery',title:'Read the carburetor stamping',summary:'A rebuild kit needs the actual carburetor model.',instructions:['Locate and photograph the carburetor make and model stamping.','Transcribe the entire model code, including its suffix. Compare it to the relevant parts reference.','If unreadable, save a blocked note with the missing detail; do not guess a kit.'],fields:[field('make','Carburetor manufacturer'),field('model','Full carburetor model / suffix'),field('photo','Carburetor stamping photo','photo'),field('reference','Identification source / notes','textarea')]},
  {id:'drive',phase:'discovery',title:'Identify drive and electrical equipment',summary:'Record the components that determine belt and lighting fitment.',instructions:['Photograph the clutch assemblies, belt markings and electrical equipment.','Record the installed starting and charging arrangement. A replacement engine may have changed the equipment.','Voltage stays unverified until supported by the actual components and an applicable service reference.'],fields:[field('drivePhoto','Drive / clutch identification photo','photo'),field('belt','Belt markings and dimensions, or explain unreadable markings','textarea'),field('clutches','Installed clutch identification / distinguishing details','textarea'),field('starting','Starting arrangement','select',{options:['Recoil only','Recoil and electric starter present','Electric starter equipment incomplete']}),field('electrical','Electrical components and documented voltage evidence','textarea')]},
  {id:'references',phase:'discovery',title:'Match the factory documents',summary:'Choose the reference for the chassis and the installed engine.',instructions:['Open the factory documents in Photos & manuals. Record the document and model column that apply.','When engine and chassis differ, retain a reference for each.','This step records your reference selection; it does not invent service settings.'],fields:[field('chassisManual','Chassis parts / operator reference and applicable model','textarea'),field('engineManual','Installed engine reference and applicable type','textarea'),field('reviewed','Reference check','check',{label:'I compared these references with the installed components.'})]},
  ...[
   ['engine-inspection','Engine & ignition','Engine & ignition','Record external condition, appropriate compression/leak-test findings and ignition assessment. Document the service procedure used; no test pressure or torque is assumed.'],
   ['fuel-inspection','Fuel system','Fuel system','Inspect tank, lines, carburetor and fittings. Record cleaning, leaks and replacement decisions.'],
   ['drive-inspection','Chaincase & drive','Chaincase & drive','Record belt, clutch, bearing, chain and sprocket condition. Identify wear before selecting parts.'],
   ['track-inspection','Track & suspension','Track & suspension','Count the actual bogie components, inspect the track, suspension, skis and steering, and record quantities and findings.'],
   ['electrical-inspection','Electrical','Electrical','Inspect wiring, grounds, lights and starting equipment. Document operating voltage and component test findings.'],
   ['body-inspection','Body & cosmetics','Body & cosmetics','Inspect fiberglass mounting areas, windshield, seat and structural body condition. Distinguish necessary repairs from cosmetic work.'],
   ['brake-inspection','Cables & brakes','Cables & brakes','Inspect throttle return, brake operation, steering fasteners and cables against the appropriate service procedure. Record anything requiring repair.']
  ].map(([id,title,category,help])=>({id,phase:'inspection',title:'Assess '+title.toLowerCase(),summary:help,instructions:[help,'Review each linked parts row below. Keep unresolved items at “Inspect”; use “Needed” for confirmed replacements, or “Not required” for items retained after inspection.','Record findings before completing the assessment.'],category,fields:[field('findings','Condition findings, measurements and replacement decisions','textarea'),field('reviewed','Assessment recorded','check',{label:'I reviewed every linked item and recorded its disposition.'})]})),
  {id:'parts-plan',phase:'planning',title:'Verify the purchase list',summary:'Resolve fitment and quantities before ordering.',instructions:['Review every item that is not “Not required”. For each item to obtain, enter a verified part number (or a precise measured service specification), supplier / service URL, and quantity.','Existing purchases remain recorded. Missing fitment information still appears as a blocker.','Use the Edit links below to fill gaps. Cosmetic items may be marked “Not required” if deferred.'],fields:[field('review','Fitment review notes, substitutions and quantity checks','textarea'),field('approved','Purchase plan checked','check',{label:'I checked the purchase list against the installed equipment and applicable references.'})]},
  {id:'repairs',phase:'repair',title:'Complete and document the repair work',summary:'Follow the verified service references and close each required item.',instructions:['Order the confirmed parts and move each item through Ordered, On hand, and Installed as the work progresses.','Use each item’s notes to record work performed, clearances, part numbers and the reference followed.','An item can also be “Not required” when retained or explicitly deferred. Do not label a repair complete solely because a part arrived.'],fields:[field('work','Work performed, service references and unresolved issues','textarea'),field('reviewed','Repair review','check',{label:'All required repair work is complete and documented.'})]},
  {id:'service-settings',phase:'testing',title:'Record the verified service settings',summary:'Resolve fuel, lubrication and electrical specifications before operation.',instructions:['Use the operator / service reference for the installed engine and equipment.','Record premix, chaincase lubricant and electrical specification with the source and applicable page.','No ratio, oil grade, quantity, gap or torque is supplied by this guide.'],fields:[field('fuel','Verified fuel / premix specification and source page','textarea'),field('chaincase','Verified chaincase lubricant / quantity and source page','textarea'),field('electrical','Verified electrical / battery specification and source page','textarea'),field('service','Other applicable service settings and reference pages','textarea')]},
  {id:'prestart',phase:'testing',title:'Complete the pre-start review',summary:'Record functional checks before any first start.',instructions:['Use the applicable service checklist and document the results below.','Confirm that the recorded repairs are complete and that fuel leaks, throttle return, stopping controls, brakes, steering, track and drive guards have been reviewed.','If any check fails or is unknown, save the blocking issue and resolve it before recording readiness. This is a project record, not a substitute for the factory procedure.'],fields:[field('checks','Pre-start checks, findings and reference used','textarea'),field('reviewer','Who reviewed the machine / applicable expertise'),field('ready','Pre-start outcome','select',{options:['Not ready / an issue remains','Ready according to the documented checks']})],checks:[['ready','Ready according to the documented checks','A pre-start issue remains unresolved.']]},
  {id:'first-run',phase:'testing',title:'Document the first controlled run',summary:'Record what happened and what needs another pass.',instructions:['Use the factory operating and first-run procedure with an appropriate reviewer.','Record actual observations, any leaks, abnormal behavior, stopping operation and follow-up work.','A failed run remains an open issue. Reopen earlier repair steps when the findings require more work.'],fields:[field('date','Run date','date'),field('observations','Run observations, checks and follow-up work','textarea'),field('outcome','Run outcome','select',{options:['Follow-up repair / diagnosis required','Recorded checks passed; no unresolved run issues']})],checks:[['outcome','Recorded checks passed; no unresolved run issues','The run has follow-up work. Keep this step open until resolved.']]},
  {id:'finish',phase:'finish',title:'Close the restoration record',summary:'Save the finished state and the next maintenance actions.',instructions:['Add finished photos and record the final work completed, retained original parts and known limitations.','Record the service references, maintenance schedule and next inspection / service action.','“Complete” means the recorded project is closed. It is not a legal registration or independent certification.'],fields:[field('finishedPhoto','Finished sled photo','photo'),field('summary','Restoration summary and retained / deferred items','textarea'),field('maintenance','Next maintenance actions and their reference','textarea'),field('handoff','Project closeout','check',{label:'The photo record, work notes, costs and maintenance actions are up to date.'})]}
 ];
 function empty(){return{version:1,sleds:{early:{steps:{}},eight:{steps:{}}}};}
 function migrate(value){if(!value||value.version!==1||!value.sleds)return empty();const result=empty();for(const sled of ['early','eight']){const records=value.sleds[sled]?.steps;if(!records||typeof records!=='object'||Array.isArray(records))continue;for(const step of steps){const record=records[step.id];if(!record||typeof record!=='object')continue;const data={};for(const f of step.fields){const v=record.data?.[f.id];if(typeof v==='string')data[f.id]=v.slice(0,20000);if(typeof v==='boolean')data[f.id]=v;}result.sleds[sled].steps[step.id]={status:['draft','blocked','complete'].includes(record.status)?record.status:'draft',data,blocker:typeof record.blocker==='string'?record.blocker.slice(0,10000):'',updated:typeof record.updated==='string'?record.updated:''};}}return result;}
 function visible(f,data){return !f.when||data[f.when[0]]===f.when[1];}
 function activeParts(state,sled,category){return state.parts.filter(p=>p.sled===sled&&(!category||p.category===category));}
 function requiredParts(state,sled){return activeParts(state,sled).filter(p=>p.category!=='Research & setup'&&p.status!=='Not required');}
 function issues(step,record,state,sled){const data=record?.data||{},errors=[];for(const f of step.fields){if(!visible(f,data))continue;const value=data[f.id];if(f.required&&(f.type==='check'?value!==true:!String(value??'').trim()))errors.push({field:f.id,message:f.type==='check'?f.label:'Record '+f.label.toLowerCase()+'.'});else if(f.type==='select'&&value&&!f.options.includes(value))errors.push({field:f.id,message:'Choose a valid '+f.label.toLowerCase()+'.'});else if(f.type==='photo'&&value&&!state.photos.some(p=>p.id===value&&p.sled===sled))errors.push({field:f.id,message:'Select an available photo for '+f.label.toLowerCase()+'.'});else if(f.type==='number'&&value&&( !Number.isInteger(Number(value))||Number(value)<f.min||Number(value)>f.max))errors.push({field:f.id,message:'Enter a supported year between '+f.min+' and '+f.max+'.'});else if(f.type==='date'&&value&&(!/^\d{4}-\d{2}-\d{2}$/.test(value)||Number.isNaN(Date.parse(value))))errors.push({field:f.id,message:'Record a valid date.'});}
 for(const [key,value,message] of step.checks||[])if(data[key]!==value)errors.push({field:key,message});
 if(step.category)for(const p of activeParts(state,sled,step.category))if(p.status==='Inspect')errors.push({part:p.id,message:'Inspection decision needed: '+p.name+'.'});
 if(step.id==='parts-plan')for(const p of requiredParts(state,sled)){if(p.status==='Inspect')errors.push({part:p.id,message:'Finish inspecting '+p.name+'.'});if(!String(p.number||'').trim())errors.push({part:p.id,message:'Verified part / service specification missing: '+p.name+'.'});try{const u=new URL(p.url);if(!['http:','https:'].includes(u.protocol))throw Error();}catch{errors.push({part:p.id,message:'Supplier / service reference link missing: '+p.name+'.'});}}
 if(step.id==='repairs')for(const p of requiredParts(state,sled)){if(p.status!=='Installed')errors.push({part:p.id,message:'Repair still open ('+p.status+'): '+p.name+'.'});else if(!String(p.notes||'').trim())errors.push({part:p.id,message:'Work notes missing: '+p.name+'.'});}
 return errors;}
 function isDone(step,state,sled,cache={}){if(Object.hasOwn(cache,step.id))return cache[step.id];const record=state.guides?.sleds?.[sled]?.steps?.[step.id];const earlier=steps.filter(x=>phases.findIndex(p=>p.id===x.phase)<phases.findIndex(p=>p.id===step.phase));return cache[step.id]=record?.status==='complete'&&issues(step,record,state,sled).length===0&&earlier.every(x=>isDone(x,state,sled,cache));}
 function blockers(step,state,sled){return steps.filter(x=>phases.findIndex(p=>p.id===x.phase)<phases.findIndex(p=>p.id===step.phase)&&!isDone(x,state,sled));}
 function summary(state,sled){const done=steps.filter(s=>isDone(s,state,sled));const next=steps.find(s=>!isDone(s,state,sled)&&blockers(s,state,sled).length===0);return{done:done.length,total:steps.length,percent:Math.round(done.length/steps.length*100),next,phase:next?phases.find(p=>p.id===next.phase):null};}
 function save(state,sled,id,data,action,blocker='',now=new Date().toISOString()){const step=steps.find(s=>s.id===id);if(!step||!['early','eight'].includes(sled))return{ok:false,errors:[{message:'Unknown sled or guide step.'}]};state.guides=migrate(state.guides);const locked=blockers(step,state,sled);if(locked.length)return{ok:false,errors:locked.map(s=>({step:s.id,message:'Complete '+s.title.toLowerCase()+' first.'}))};const rec={status:action==='complete'?'complete':action==='blocked'?'blocked':'draft',data:{...data},blocker:String(blocker||''),updated:now};const errors=action==='complete'?issues(step,rec,state,sled):action==='blocked'&&!String(blocker).trim()?[{message:'Describe the issue so the next prompt can help resolve it.'}]:[];if(errors.length)return{ok:false,errors};state.guides.sleds[sled].steps[id]=rec;return{ok:true,record:rec,next:summary(state,sled).next};}
 const api={phases,steps,empty,migrate,visible,issues,isDone,blockers,summary,save,requiredParts};root.RestorationGuide=api;if(typeof module!=='undefined'&&module.exports)module.exports=api;
})(typeof globalThis!=='undefined'?globalThis:this);
